tile := v.tile_px * v.scale
// v2-scale-depth: the grid clips to the WORLD rect (the fit margins stay
// clean paper — MM's whitespace read; the old full-window loop drew grid
// lines over the margins). Same deterministic tile stepping.
x0 := v.off_x
x1 := v.off_x + f32(v.world_w) * v.scale
y0 := v.off_y
y1 := v.off_y + f32(v.world_h) * v.scale
x := x0
for x <= x1 {
	rl.DrawLine(i32(x), i32(y0), i32(x), i32(y1), grid_soft)
	x += tile
}
